"""Build Beth's personal site from the approved career and publication sources.
Run python scripts/build_site.py. This does not change either PDF CV.
"""
from pathlib import Path
from html import escape as e
from datetime import date
import json,re
ROOT=Path(__file__).resolve().parents[1]
facts=json.loads((ROOT/'content/career.json').read_text())
recent=json.loads((ROOT/'content/recent-work.json').read_text())['items']
sections=json.loads((ROOT/'content/cv-sections.json').read_text())
NAV=[('index.html','Home'),('work.html','Leadership'),('writing.html','Writing'),('speaking.html','Speaking'),('cv.html','CV')]
def slug(s):return re.sub('[^a-z0-9]+','-',s.lower()).strip('-')
def external(url,label,cls=''):
 return f'<a href="{e(url,quote=True)}" target="_blank" rel="noopener"'+(f' class="{cls}"' if cls else '')+f'>{e(label)}</a>'
def layout(file,title,description,body):
 nav=''.join(f'<a href="{href}"'+(' class="nav-cv"' if label=='CV' else '')+(' aria-current="page"' if href==file else '')+f'>{label}</a>' for href,label in NAV)
 canonical='https://bethrudden.ai/'+('' if file=='index.html' else file)
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{e(title)}</title><meta name="description" content="{e(description,quote=True)}"><link rel="canonical" href="{canonical}">
<meta property="og:title" content="{e(title,quote=True)}"><meta property="og:description" content="{e(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://bethrudden.ai/beth.jpg"><meta property="og:image:alt" content="Beth Rudden at SXSW EDU"><meta name="twitter:card" content="summary_large_image">
<link rel="icon" href="beth-headshot.jpg" type="image/jpeg"><link rel="stylesheet" href="site.css"><script src="analytics-consent.js" defer></script>
</head><body><a class="skip" href="#main-content">Skip to content</a>
<header class="site-header"><div class="wrap header-inner"><a class="brand" href="index.html">Beth Rudden<span aria-hidden="true">.</span></a><nav class="site-nav" aria-label="Main navigation">{nav}</nav></div></header>
<main id="main-content">{body}</main>
<footer class="site-footer" id="contact"><div class="wrap"><div class="footer-top"><div><div class="footer-name">Beth Rudden.</div><p>Building teams, growing businesses, and creating systems that help people.</p></div><nav class="footer-links" aria-label="Contact and resources"><a href="cv.html">Full CV</a><a href="Beth-Rudden-CV.pdf">Download CV</a><a href="mailto:beth@bast.ai">Email Beth</a><a href="https://www.linkedin.com/in/brudden/" target="_blank" rel="noopener">LinkedIn</a></nav></div><div class="footer-bottom"><span>Denver, Colorado · © 2026 Beth Rudden</span><a href="privacy.html">Privacy &amp; accessibility</a></div></div></footer></body></html>'''
def intro(kicker,title,text,actions=''):
 return f'<div class="wrap"><header class="page-intro"><p class="eyebrow">{e(kicker)}</p><h1>{title}</h1><p class="lede">{text}</p>{actions}</header></div>'
def date_text(value):
 d=date.fromisoformat(value);return f'{d:%B} {d.day}, {d.year}'
def entries(items,descriptions=True,upcoming=False):
 output='<div class="list">'
 for r in items:
  category='Upcoming' if upcoming else ('Essay' if r['status']=='Published essay' else 'Field notes' if r['status']=='Published field notes' else 'Column' if r['status']=='Published column' else 'Podcast' if r['status']=='Published podcast' else 'Talk')
  output+=f'<article class="entry"><div class="entry-meta"><time datetime="{r["date"]}">{date_text(r["date"])}</time><span>{category}</span></div><div><h3>{external(r["url"],r["title"])}</h3><p class="publisher">{e(r["publisher"])}</p>'
  if descriptions and not upcoming:output+=f'<p>{e(r["focus"])}</p>'
  output+='</div></article>'
 return output+'</div>'
cv_actions='<div class="actions"><a class="button" href="cv.html">Read my full CV <span aria-hidden="true">↗</span></a><a class="button secondary" href="Beth-Rudden-CV.pdf">Download CV · PDF <span aria-hidden="true">↓</span></a></div>'
# Home: identity first, followed by the breadth of Beth's work.
home=f'''<div class="wrap"><section class="hero"><div><p class="eyebrow">Business &amp; technology leadership</p><h1>Beth Rudden.</h1><p class="lede">I build and lead teams that turn complex problems into systems people can understand, trust, and use.</p><p class="intro">I connect technical depth with business judgment—and a lifelong curiosity about people—to help institutions serve their communities better.</p>{cv_actions}<p class="roles">Founder &amp; CEO, Bast AI · IBM Distinguished Engineer, appointed 2016 · Board trustee · Author</p></div><figure class="portrait"><img src="beth.jpg" alt="Beth Rudden at SXSW EDU, wearing blue glasses and an almond-blossom scarf" width="720" height="900" fetchpriority="high"><figcaption>At SXSW EDU · Technology, learning, and human possibility.</figcaption></figure></section>
<section class="section"><div class="section-head"><div><p class="eyebrow">The work, connected</p><h2>People. Institutions. Possibility.</h2></div><a class="text-link" href="work.html">Explore my leadership →</a></div><div class="three-col"><article><div class="number">01 / Lead</div><h3>Build the team and the business.</h3><p>I have owned and grown businesses, developed leaders, and brought people together around problems worth solving.</p></article><article><div class="number">02 / Build</div><h3>Make knowledge useful.</h3><p>At Bast, I lead engineers and domain experts building AI that makes answers traceable and uncertainty visible.</p></article><article><div class="number">03 / Serve</div><h3>Help institutions help people.</h3><p>Through board service, teaching, writing, and public leadership, I connect technology with the lives it affects.</p></article></div></section></div>
<section class="band"><div class="wrap split"><div><p class="eyebrow">How I see the work</p><h2>Understand the people.<br>Build what helps.</h2></div><div><p>My background in anthropology and engineering shapes how I lead: understand the people and the mission, make the problem clear, and build the organization capable of solving it.</p><p>That thread connects a 23-year career at IBM, founding Bast, and serving institutions dedicated to science, education, and care.</p><div class="actions"><a class="text-link" href="work.html">Read my story →</a></div></div></div></section>
<div class="wrap"><section class="section" style="border-top:0"><div class="split"><div><p class="eyebrow">The work in five outcomes</p><h2>What that leadership<br>has made possible.</h2></div><ol class="outcomes">{''.join('<li>'+e(x)+'</li>' for x in facts['story'])}</ol></div></section>
<section class="section"><div class="section-head"><div><p class="eyebrow">Writing &amp; conversations</p><h2>Ideas I’m working through.</h2></div><a class="text-link" href="writing.html">More writing →</a></div>{entries([recent[5],recent[0],recent[1]])}</section>
<section class="section"><div class="split"><div><p class="eyebrow">Service &amp; stewardship</p><h2>Beyond the company.</h2></div><div><p>I serve on the boards of trustees of the Denver Museum of Nature &amp; Science and Maryville University, and on the advisory board of Northwestern University’s Center for Advancing Safety of Machine Intelligence.</p><p>These roles connect the things I care about: how people learn, how knowledge is shared, and how institutions earn trust.</p><div class="actions"><a class="text-link" href="work.html#board-service">Board service &amp; public leadership →</a></div></div></div></section></div>'''
(ROOT/'index.html').write_text(layout('index.html','Beth Rudden — Leadership, technology, and systems that help people','Beth Rudden: business and technology leader, founder of Bast AI, IBM Distinguished Engineer, board trustee, and author. Explore her work and full CV.',home))
# Replace the old consultancy funnel at its existing URL.
work=intro('Leadership & service','The human problem<br>comes first.','I build organizations that can turn difficult problems into useful systems. That takes technical judgment, business ownership, and people who have the confidence and authority to do their best work.',cv_actions)
work+='''<div class="wrap"><section class="work-row" id="bast"><div class="work-label">2022–present<br>Founder &amp; CEO · Bast AI</div><div><h2>Build a company around understanding.</h2><p>I founded Bast to build explainable AI for healthcare and other regulated institutions. I lead engineers and domain experts, connect their work through shared standards, and own client outcomes from scoping through production.</p><p>We build the knowledge layer underneath AI so answers can be traced to evidence and uncertainty is visible. Our work helps people understand care and access expertise in difficult environments.</p><p>Over four years, I built the business, its teams, and its partnerships, securing $1.5M in revenue and $750K in investment. I also led the transition to agentic delivery, with human review of every change.</p><a class="text-link" href="https://www.bast.ai/" target="_blank" rel="noopener">Explore Bast’s work →</a></div></section>
<section class="work-row" id="ibm"><div class="work-label">23 years at IBM<br>Business &amp; technical leadership</div><div><h2>Grow the business. Grow the people.</h2><p>At IBM, I owned the Content Intelligence and AI at Scale businesses, led their teams, and carried responsibility for their P&amp;Ls. I established the Trustworthy AI Center of Excellence and recruited its leadership.</p><p>As Chief Data Officer for IBM’s services division, I led workforce transformation and large-scale endpoint remediation through enterprise disruption. The work helped people move into new roles while addressing urgent security and data-protection needs.</p><p>I created the data-science profession and secured its accreditation through The Open Group, building the skills and professional standards needed to deliver AI at global scale.</p><p class="small">IBM Distinguished Engineer, appointed 2016.</p></div></section>
<section class="work-row" id="board-service"><div class="work-label">Board service<br>Science, education &amp; AI</div><div><h2>Steward institutions that matter.</h2><p>My board work carries the same commitment as my work in technology: help institutions serve people better, and keep the human purpose visible as they change.</p><ul class="board-list"><li>Denver Museum of Nature &amp; Science<span>Board of Trustees</span></li><li>Maryville University<span>Board of Trustees</span></li><li>Northwestern University · CASMI<span>Advisory Board, Center for Advancing Safety of Machine Intelligence</span></li></ul></div></section>
<section class="work-row" id="public-leadership"><div class="work-label">Public leadership<br>Policy, professions &amp; learning</div><div><h2>Make the difficult questions discussable.</h2><p>I have testified before the Colorado Senate Judiciary Committee on AI consumer protection and joined public conversations about how we govern technology. I write and speak about human judgment, explainability, and the responsibilities of the people building and using AI.</p><p>Developing people is part of this work: from the data-science profession to sponsorship, mentoring, and helping others see what they are capable of doing.</p><a class="text-link" href="speaking.html">Talks &amp; conversations →</a></div></section>
<section class="section image-story"><img src="beth-stage.jpg" alt="Beth Rudden speaking on a panel at SXSW EDU" width="560" height="700" loading="lazy"><div><p class="eyebrow">An anthropologist’s perspective</p><h2>I started my career in ruins.</h2><p>Studying archaeology and anthropology taught me to look for the people behind the artifacts: what they understood, what they valued, and how they made sense of their world.</p><p>I bring that perspective to organizations and technology. Understanding the human context is where useful work begins.</p><div class="actions"><a class="text-link" href="writing.html">Read my writing →</a></div></div></section>
<section class="contact-note" id="inquiry"><h2>Continue the conversation.</h2><p>For leadership opportunities, board service, speaking, or a thoughtful exchange of ideas, <a href="mailto:beth@bast.ai">email me</a> or <a href="https://www.linkedin.com/in/brudden/" target="_blank" rel="noopener">connect on LinkedIn</a>.</p></section></div>'''
(ROOT/'work.html').write_text(layout('work.html','Leadership & Service — Beth Rudden','Beth Rudden’s leadership at Bast AI and IBM, workforce transformation, board service, and public leadership.',work))
writing=intro('Essays, books & publications','Making sense<br>of what we build.','I write about people, knowledge, and the choices that shape technology—drawing on anthropology, engineering, and the experience of leading teams and businesses.','<div class="actions"><a class="button" href="https://bastai.substack.com/" target="_blank" rel="noopener">Read Ground Truth ↗</a></div>')
writing+='<div class="wrap"><section class="content-section"><h2>Recent writing</h2>'+entries([r for r in recent if r['category']=='Publications'])+'</section>'
writing+='''<section class="content-section"><p class="eyebrow">Books</p><div class="books"><article class="book"><h3><a href="https://aifortherestofus.us" target="_blank" rel="noopener">AI for the Rest of Us</a></h3><p>Co-author</p><p class="small">Nominated #1 book to read in 2024 by Constellation Research.</p></article><article class="book"><h3>Julian Steward and the Great Basin</h3><p>Co-author and editor</p><p class="small">Anthropology and the relationships between people and their environments.</p></article></div></section>
<section class="content-section prose"><h2>More places to read</h2><p><a href="https://bastai.substack.com/p/hey-boss-7-dead-giveaways-youre-treating" target="_blank" rel="noopener">7 Ways to Spot Someone Who Thinks the AI Understands Them</a> is among my widely read essays on how people relate to AI.</p><p>My work also includes contributions to Cognitive World and VentureBeat, and the <a href="https://www.enterpriseaiworld.com/Articles/MoreNews.aspx?ContextSubtypeID=863" target="_blank" rel="noopener">Crossing the AI Chasm</a> column in Enterprise AI World.</p><p><a href="https://medium.com/@ibethrudden" target="_blank" rel="noopener">Medium</a> · <a href="https://scholar.google.com/scholar?q=Beth+Rudden&amp;hl=en&amp;as_sdt=0,6" target="_blank" rel="noopener">Google Scholar</a> · <a href="cv.html#books">Full CV &amp; bibliography</a></p></section></div>'''
(ROOT/'writing.html').write_text(layout('writing.html','Writing & Publications — Beth Rudden','Essays, books, and publications by Beth Rudden on AI, human judgment, leadership, and knowledge.',writing))
speaking=intro('Talks, podcasts & public leadership','Conversations<br>that move the work.','On stage and in conversation, I connect the technical choices we make with the people and institutions they affect.')
speaking+='<div class="wrap"><section class="content-section"><h2>Recent appearances</h2>'+entries([r for r in recent if r['category']=='Appearances'])+'</section><section class="content-section"><h2>Upcoming speaking</h2><p class="small" style="margin-bottom:24px">Scheduled appearances · November 2026</p>'+entries([r for r in recent if r['category']=='Upcoming listings'],upcoming=True)+'</section>'
speaking+='''<section class="content-section"><h2>More conversations</h2><div class="three-col"><article><h3>Masters of Scale</h3><p>Strategy Sessions with Reid Hoffman and Rana el Kaliouby.</p><p><a href="https://www.youtube.com/watch?v=Bd9xqcAqVYU" target="_blank" rel="noopener">Watch the conversation ↗</a></p></article><article><h3>SXSW EDU</h3><p>AI’s Leap: Shaping Tailored Learning · 2024</p><p><a href="https://www.youtube.com/watch?v=hcqpT8yilPg" target="_blank" rel="noopener">Watch the session ↗</a></p></article><article><h3>DataStax</h3><p>Redefining AI Ethics: The Key Role of Explainability</p><p><a href="https://www.datastax.com/resources/podcast/redefining-ai-ethics-explainability" target="_blank" rel="noopener">Listen to the conversation ↗</a></p></article></div></section>
<section class="content-section prose"><h2>Public leadership</h2><p>My public work includes testimony before the Colorado Senate Judiciary Committee, conversations on AI regulation at Silicon Flatirons, and speaking at the Denver Museum of Nature &amp; Science.</p><p>Other appearances include EarthX, the Cynefin Exploratory, Concordia Live, the Denver Council on Foreign Relations, the Salzburg Dialogue, and the Global Female Leaders Economic Forum.</p><p><a href="cv.html#selected-keynotes-public-leadership">See the full speaking record →</a></p></section><section class="contact-note"><h2>Invite a conversation.</h2><p>For speaking and interview inquiries, <a href="mailto:beth@bast.ai">email Beth</a>.</p></section></div>'''
(ROOT/'speaking.html').write_text(layout('speaking.html','Speaking & Conversations — Beth Rudden','Beth Rudden’s recent talks, podcast appearances, public leadership, and upcoming speaking engagements.',speaking))
# Preserve every approved full-CV section and its contents, with direct navigation.
order=['Executive Profile','The work in five outcomes','Professional Experience','Board & Advisory','Writing & Expert Contributions','Selected Podcasts & Interviews','Selected Keynotes & Public Leadership','Upcoming Speaking','Patents, Publications & Open Technical Assets','Books','Awards & Recognition','Policy & Public Accountability','Education & Credentials','IBM Appointments','Professional Certifications']
assert set(order)==set(sections)
cv=intro('Beth Rudden','Full CV.','Business and technology executive · Founder &amp; CEO, Bast AI · IBM Distinguished Engineer, appointed 2016 · Board trustee','<div class="actions"><a class="button" href="Beth-Rudden-CV.pdf">Download full CV · PDF ↓</a><a class="button secondary" href="mailto:beth@bast.ai">Contact Beth</a></div><p class="small" style="margin-top:16px">Updated October 15, 2026 · Four-page PDF</p>')
cv+='<div class="wrap cv-layout"><aside class="cv-index"><details open><summary>On this page</summary><nav aria-label="CV sections">'+''.join(f'<a href="#{slug(s)}">{e(s)}</a>' for s in order)+'</nav></details></aside><div class="main">'
for s in order:cv+=f'<h2 class="section-title" id="{slug(s)}">{e(s)}</h2>\n'+'\n'.join(sections[s])+'\n'
cv+='</div></div>'
(ROOT/'cv.html').write_text(layout('cv.html','Full CV — Beth Rudden','Beth Rudden’s full CV: business leadership, teams, Bast AI, IBM, board service, patents, publications, and speaking. Read online or download the PDF.',cv))
privacy=intro('Privacy & accessibility','A site you can<br>understand.','This is a static professional site. It does not sell visitor data or run advertising pixels. Optional analytics load only when a visitor chooses to allow them.')
privacy+='''<div class="wrap"><div class="prose" style="padding-bottom:60px"><h2>Analytics</h2><p>Optional Google Analytics 4 helps us understand which pages, CV downloads, outbound links, and email links are useful. Analytics are off until you choose “Allow analytics” in the cookie notice. Choosing “Necessary only” keeps Google Analytics from loading. The measurement ID is G-FL8JCB0PXZ.</p><button class="button" type="button" onclick="window.brOpenConsentPreferences &amp;&amp; window.brOpenConsentPreferences()">Change analytics choice</button><h2>Cookies and local storage</h2><p>The site stores a preference named <code>br_cookie_consent</code> to remember your choice. When analytics are allowed, Google Analytics may set analytics cookies according to Google’s controls and retention settings.</p><h2>Contact links</h2><p>Email links open your email application. This site has no inquiry form and does not store messages. You decide whether to send an email.</p><h2>Accessibility</h2><p>The site uses semantic headings, keyboard-accessible navigation, visible focus states, descriptive image text, and layouts that adapt to screen size. If something gets in your way, please let me know.</p><h2>Questions</h2><p>For privacy or accessibility questions, email <a href="mailto:beth@bast.ai">beth@bast.ai</a>.</p><p class="small">Updated October 15, 2026.</p></div></div>'''
(ROOT/'privacy.html').write_text(layout('privacy.html','Privacy & Accessibility — Beth Rudden','Privacy, analytics choices, and accessibility information for bethrudden.ai.',privacy))
urls=['','work.html','writing.html','speaking.html','cv.html','privacy.html']
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>https://bethrudden.ai/{p}</loc><lastmod>2026-10-15</lastmod></url>\n' for p in urls)+'</urlset>\n')
print('Built six pages with shared navigation, direct CV access, and approved career content.')
